+
+  ship->vessel_type = VESSEL_BOAT;
+  CuAssertIntEquals(tc, 10, vessel_damage_sail(NULL, ship, 10));
+  ship->mainsail = 3;
+  vessel_damage_sail(NULL, ship, 10);
+  CuAssertIntEquals(tc, 0, ship->mainsail);
+
+  damage_clear();
+}
