+  ship->rarmor = 65;
+  ship->rinternal = 23;
+  ship->mainsail = 0;
+  CuAssertTrue(tc, vessel_prize_disabled(ship, &fixture.captain));
+  ship->mainsail = 140;
+  ship->colors_struck_ticks = 5;
+  CuAssertTrue(tc, vessel_prize_disabled(ship, &fixture.captain));
+  ship->colors_struck_ticks = 0;
+
+  /* Abandoned at sea: nobody conscious aboard but the claimant; a sleeper
+   * does not count. */
