+/* Clear the captured output before the next command. */
+static void damage_reset_output(struct descriptor_data *descriptor, char *output, size_t size)
+{
+  memset(output, 0, size);
+  descriptor->bufptr = 0;
+  descriptor->bufspace = (int)(size - 1);
+}
